import * as T from './vendor/three.module.js';
import {detailBoxes} from './detail-instances.js?v=48.0.0';
export const gardenNote=s=>(s.commonsNotes||[]).find(n=>n.kind==='garden'&&n.mallId===s.mallId&&n.floor===(s.floor||0));
export const GARDEN_OBSERVATIONS={leaves:{name:'Layers of leaves',leaf:'#52735a',flower:'#e0d5a8'},color:{name:'A small patch of color',leaf:'#66816a',flower:'#c78068'},shade:{name:'Patterns of shade',leaf:'#607775',flower:'#a4a0bd'}};
export function gardenGuideHTML(s,esc){const n=gardenNote(s),saved=n&&GARDEN_OBSERVATIONS[n.choice];return `<div class="modal-body garden-field-guide"><span class="eyebrow">ORIGINAL MALLSIDE POCKET GARDEN · FREE TO READ</span><h3>Look a little closer.</h3><p>Layered leaves, a warm flower or the shadows between stems: three ways to notice this small garden. The planting is original game scenery, not a botanical care guide.</p><div class="care-summary">${Object.values(GARDEN_OBSERVATIONS).map(v=>`<span>${esc(v.name)}</span>`).join('')}</div><p class="garden-saved-note">${saved?`Your observation here: <strong>${esc(saved.name)}</strong> · day ${n.day}.`:'No garden observation saved on this floor yet.'}</p><p>Your saved choice colors this floor’s planting and notebook marker. Reading this card spends no money or game time and awards no XP. Recording an observation keeps its existing four-minute activity and once-per-day rules.</p><button class="button orange wide" data-action="center-stop" data-type="fixture" data-id="commons-garden" data-floor="${s.floor||0}">Visit this garden study</button><button class="button secondary wide" data-action="commons-notebook">My discovery notebook</button><button class="button secondary wide" data-action="close">Back to the mall</button></div>`;}
// Curved instanced leaves and petals remain inside the existing 30×30 collision footprint.
export function buildGardenStudy(w,x,z,theme){
 const root=new T.Group();root.position.set(x,30,z);w.scene.add(root);const sphere=new T.SphereGeometry(1,8,5),cylinder=new T.CylinderGeometry(1,1,1,12),leafMat=new T.MeshStandardMaterial({color:theme.plant,roughness:.88}),bloomMat=new T.MeshStandardMaterial({color:'#ffffff',roughness:.92}),markerMat=new T.MeshStandardMaterial({color:'#ded2b9',roughness:.9});for(const r of [sphere,cylinder,leafMat,bloomMat,markerMat])w.resources.add(r);
 const dummy=new T.Object3D(),put=(mesh,i,p,s,turn=0,tilt=0)=>{dummy.position.set(...p);dummy.scale.set(...s);dummy.rotation.set(0,turn,tilt);dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);};
 const instances=(geometry,material,count,parent=root)=>{const m=new T.InstancedMesh(geometry,material,count);m.castShadow=m.receiveShadow=true;parent.add(m);return m;},pots=instances(cylinder,w.mat('#ba9774'),4),soil=instances(cylinder,w.mat('#655947'),4),sprigs=[],blooms=[];
 for(const [i,[dx,dz]]of [[-7,-6],[6,-5],[-5,7],[7,7]].entries()){
  put(pots,i,[dx,1.7,dz],[3.3,3.4,3.3]);put(soil,i,[dx,3.45,dz],[2.9,.15,2.9]);const stem=new T.Group();stem.position.set(dx,3.5,dz);root.add(stem);const leaves=instances(sphere,leafMat,5,stem);put(leaves,0,[0,3.7,0],[.35,3.7,.35]);for(let j=1;j<5;j++){const angle=j*2.4;put(leaves,j,[Math.cos(angle)*1.6,1.6+j*.8,Math.sin(angle)*1.5],[2.6,.45,1],-angle,(j%2?1:-1)*.35);}const flower=instances(sphere,bloomMat,6,stem);for(let j=0;j<5;j++){const a=j/5*Math.PI*2;put(flower,j,[Math.cos(a)*1.45,7.5,Math.sin(a)*1.45],[1.7,.5,1.1],-a);flower.setColorAt(j,new T.Color(theme.flowers));}put(flower,5,[0,8,0],[.7,.35,.7]);flower.setColorAt(5,new T.Color('#d5b163'));sprigs.push(stem);blooms.push(flower);
 }
 const stones=instances(sphere,w.mat('#ffffff'),9);for(let i=0;i<9;i++){const a=i*2.399;put(stones,i,[Math.cos(a)*11,.35,Math.sin(a)*11],[1.3,.5,1]);stones.setColorAt(i,new T.Color(i%2?'#bcb6a1':'#d4c9ae'));}
 detailBoxes(w,root,[[10,.7,10,8,.7,6,'#eee5d5'],[10,1.2,10,8,.3,6,'#816d52'],[11,1.4,10,1,.15,5,'#d6ba81']]);const marker=w.box(7.5,1.55,10,1.4,.2,4,markerMat,root);root.userData={originalPlanting:true,footprint:30};w.gardenSprigs??=[];w.gardenSprigs.push(...sprigs);w.gardenStudies??=[];w.gardenStudies.push({root,leafMat,markerMat,marker,blooms,defaultLeaf:theme.plant,defaultFlower:theme.flowers,signature:null});if(w.canvas)w.canvas.dataset.gardenDetailRevision='48';updateGardenStudies(w);return root;
}
export function updateGardenStudies(w){
 const time=Number.isFinite(w.t)?w.t:0;for(const[i,stem]of(w.gardenSprigs||[]).entries())stem.rotation.z=w.state.preferences.reducedMotion?0:Math.sin(time*.8+i*1.7)*.035;
 const note=gardenNote(w.state),signature=note?.choice||'unrecorded',choice=GARDEN_OBSERVATIONS[signature];for(const g of w.gardenStudies||[]){if(g.signature===signature)continue;g.leafMat.color.set(choice?.leaf||g.defaultLeaf);g.markerMat.color.set(choice?.flower||'#ded2b9');g.marker.visible=!!choice;for(const bloom of g.blooms){for(let i=0;i<5;i++)bloom.setColorAt(i,new T.Color(choice?.flower||g.defaultFlower));bloom.instanceColor.needsUpdate=true;}g.signature=signature;}if(w.canvas&&w.gardenStudies?.length)w.canvas.dataset.gardenObservation=signature;
}
